import json
import logging
import os
import time
import traceback

from robot.libraries.BuiltIn import BuiltIn
from taf.internal.robot_typecasts import time_to_seconds
from taf.rfrl.bts.connections.device_aliases import ssh_bts_du
from taf.rfrl.common_resources.oam_kpi.report_oam_kpi import report_oam_kpi, report_oam_kpi_success_rate
from taf.rfrl.procedures.resources.python.OAM_KPI.GenericRunnerBase import GenericRunnerBase
from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl
from taf.rfrl.utilities.logger.custom_logger import log_info_to_console, log_warn_to_console
from taf.rfrl.utilities.robot.RobotKWRunner import run_as_robot_kw as convert_to_robot_kw
from taf.ul.moler.converter.interface import get_devices_from_regex
from taf.ul.oam_kpi_calculations import oam_kpi_calculations
from taf.ul.oam_kpi_calculations.exceptions import OamKpiCalculationsException
from taf.ul.oam_kpi_calculations.utilities import get_last_disconnected_ims_log


class GenericRunnerKPI(GenericRunnerBase):

    def __init__(self, operation_description, kpi_names, bts_id=0, du_id=0, additional_allowed_alarms=None,
                 temp_allowed_alarms=None, critical_alarms=None, temp_critical_alarms=None, report_to_rep=True,
                 enable_listener=True, add_default_logs=True, **kwargs):
        self.kpi_names = kpi_names
        self._oam_kpi = convert_to_robot_kw(oam_kpi_calculations)
        self.report_to_rep = report_to_rep
        self.calculate_kpi = True
        self.custom_timestamps = {}
        self._ims_path = None
        self._all_results = {}
        self._kpi_params = {}
        self.kpi_rfc_names = ["kpi1b", "kpi1c", "kpi41"]
        self._collect_disconnected_ims_log = False
        for kpi_name in kpi_names:
            self._all_results[kpi_name] = {}
            self._all_results[kpi_name]['results'] = {}
        super(GenericRunnerKPI, self).__init__(operation_description, bts_id, du_id, additional_allowed_alarms,
                                               temp_allowed_alarms, critical_alarms, temp_critical_alarms,
                                               enable_listener, add_default_logs, **kwargs)
        self.collect_ims_snapshot = self.log.collect_ims_log
        self.ims_du_id = convert_to_robot_kw(self.get_ims_du_id)

    def run_in_loop(self, iterations=1, timeout=480, start_iteration=1, target=None):
        """
        Run operation in loop.

        :param iterations:          number of iterations
        :param start_iteration:     use to specify log directory
        :param timeout:             timeout for 'wait_for_all_cells_onair' after reset
        :param target:              targets for calculated KPIS: could be passed as dict:
        :return: dict: calculated KPIs from each iterations
                    results = {
                        'kpi1a': {
                            'avg': 470.999,
                            'failed': 0,
                            'passed': 2,
                            'ratio': 1.0,
                            'results': [{'delta': 451.932, 'status': 'PASSED'},
                                        {'delta': 490.066, 'status': 'PASSED'}],
                            'target': 600.0},
                        'kpi1b': {
                            'avg': 470.999,
                            'failed': 0,
                            'passed': 2,
                            'ratio': 1.0,
                            'results': [{'delta': 451.932, 'status': 'PASSED'},
                                        {'delta': 490.066, 'status': 'PASSED'}],
                            'target': 600.0},
                        'kpi1c': {
                            'avg': 468.1325,
                            'failed': 0,
                            'passed': 2,
                            'ratio': 1.0,
                            'results': [{'delta': 447.836, 'status': 'PASSED'},
                                        {'delta': 488.429, 'status': 'PASSED'}],
                            'target': 600.0}}
        """
        convert_to_robot_kw(self._add_target_to_results, target=target)
        super(GenericRunnerKPI, self).run_in_loop(iterations=iterations, timeout=timeout,
                                                  start_iteration=start_iteration)

    def _fail_iteration(self):
        super(GenericRunnerKPI, self)._fail_iteration()
        for kpi_name in self.kpi_names:
            iteration = "iteration_{}".format(self._iteration_number)
            self._all_results[kpi_name]['results'][iteration] = {'delta': None, 'status': 'FAILED'}

    def run_preconditions(self, iteration):
        convert_to_robot_kw(self.bbu.connect, bts_id=self.bts_id, du_id=self.ims_du_id, force=True)
        super(GenericRunnerKPI, self).run_preconditions(iteration)

    def run_postconditions(self):
        if self.calculate_kpi is True:
            logging.debug("Wait for 2 seconds to ensure IMS data from all cells is available before collection")
            time.sleep(2)
            convert_to_robot_kw(self.calculate_kpi_and_check_status)
        super(GenericRunnerKPI, self).run_postconditions()

    def actions_after_loop(self):
        if self.calculate_kpi is True:
            BuiltIn().log(self._all_results)
            self._calculate_final_results(runs=int(self._iteration_number))
        super(GenericRunnerKPI, self).actions_after_loop()

    def teardown_connections(self):
        super(GenericRunnerKPI, self).teardown_connections()
        convert_to_robot_kw(function=self.bbu.disconnect, bts_id=self.bts_id, du_id=self.ims_du_id)

    def _add_target_to_results(self, target):
        self._target = target
        for kpi_name in self.kpi_names:
            if target:
                if isinstance(target, dict):
                    _target = target[kpi_name]
                else:
                    _target = target
                self._all_results[kpi_name]['target'] = float(time_to_seconds(_target))
            else:
                self._all_results[kpi_name]['target'] = None

    def calculate_kpi_and_check_status(self):
        self.custom_logger(log_info_to_console, msg="Collect IMS and calculate KPI", log_hierarchy=2)
        self._ims_path = convert_to_robot_kw(function=self.collect_ims_snapshot, bts_id=self.bts_id,
                                             du_id=self.ims_du_id, log_dir=self._iteration_log_path)
        if self._collect_disconnected_ims_log:
            ims_session_file_path = convert_to_robot_kw(get_last_disconnected_ims_log,
                                                        log_dir=self._iteration_log_path)
            self._ims_path = [ims_session_file_path, self._ims_path]
        try:
            results = convert_to_robot_kw(function=self._oam_kpi.calculate_kpis, kpi_names=self.kpi_names,
                                          kpi_params=self._kpi_params, ims_file_path=self._ims_path)
            convert_to_robot_kw(function=self._oam_kpi.save_results_to_file,
                                file_path=os.path.join(self._iteration_log_path,
                                                       '{}_KPIs.json'.format(
                                                           ssh_bts_du.format(self.bts_type, self.bts_id, self.du_id))))
            logging.debug("KPI results: {}".format(results))

            all_kpi_statuses = []
            iteration = "iteration_{}".format(self._iteration_number)
            rfc_kpis = convert_to_robot_kw(self.calculate_rfc_cells_kpi, results=results) if self._rfc_cells else None
            for kpi_name in self.kpi_names:
                if kpi_name not in list(self.custom_timestamps):
                    delta = convert_to_robot_kw(function=self._oam_kpi.get_all_deltas, kpi_name=kpi_name)[0]
                else:
                    custom_end_time_type = self.custom_timestamps[kpi_name]["end_point"]
                    custom_start_time_type = self.custom_timestamps[kpi_name]["start_point"]
                    end_time = results[kpi_name][0]["detailed_results"][custom_end_time_type]["end_point"]
                    start_time = results[kpi_name][0]["detailed_results"][custom_start_time_type]["start_point"]
                    delta = (end_time - start_time).total_seconds()
                target = self._all_results[kpi_name]['target']
                kpi_status = None
                if target and delta:
                    delta = round(delta, 2)
                    if delta > self._all_results[kpi_name]['target']:
                        kpi_status = 'FAILED'
                    else:
                        kpi_status = 'PASSED'
                    self.custom_logger(log_info_to_console, msg="{}: [STATUS: {}, TIME: {}, TARGET: {}]".
                                       format(kpi_name, kpi_status, delta, target), log_hierarchy=3)
                    all_kpi_statuses.append(kpi_status)
                self._all_results[kpi_name]['results'][iteration] = {'delta': delta, 'status': kpi_status}
                if rfc_kpis is not None:
                    for rf_cell in list(rfc_kpis):
                        if kpi_name in list(rfc_kpis[rf_cell]):
                            self._all_results[kpi_name]['results'][iteration][rf_cell] = rfc_kpis[rf_cell][kpi_name]
            if self._current_status is None and all_kpi_statuses:
                self._current_status = 'FAILED' if 'FAILED' in all_kpi_statuses else 'PASSED'
            elif self._current_status is None and self._target is None:
                self._current_status = 'PASSED'
            self.custom_logger(log_info_to_console,
                               msg="Iteration STATUS: {}".format(self._current_status), log_hierarchy=2)
            if self.report_to_rep:
                convert_to_robot_kw(function=report_oam_kpi, oam_kpi_results=results, oam_kpi_targets=self._target)
            convert_to_robot_kw(function=self._oam_kpi.clear_results)
        except OamKpiCalculationsException as e:
            self._fail_iteration()
            convert_to_robot_kw(function=log_warn_to_console,
                                msg="Calculate KPI Failed: {}".format(repr(e)), log_hierarchy=2)

    def _calculate_final_results(self, runs):
        log_info_to_console("Calculate final results")

        def _count_statuses(_results, expected_status):
            count = 0
            for iteration in _results:
                record = _results[iteration]
                status = record.get('status', None)
                if status and status == expected_status:
                    count = count + 1

            return count

        try:
            dump_all_results = dict(self._all_results)
            del dump_all_results["bts_build"]
            for kpi_name in dump_all_results:
                results = dump_all_results[kpi_name]['results']
                passed = _count_statuses(results, 'PASSED')
                failed = _count_statuses(results, 'FAILED')
                passed_ratio = passed / float(runs)
                all_deltas = [results[iteration]['delta'] for iteration in results if results[iteration]['delta']]
                all_passed_deltas = [results[iteration]['delta'] for iteration in results
                                     if results[iteration]['delta'] and results[iteration]['status'] == 'PASSED']
                passed_avg = round(sum(all_passed_deltas) / float(passed), 2) if passed else None
                total_avg = round(sum(all_deltas) / float(runs), 2)

                dump_all_results[kpi_name]['passed'] = passed
                dump_all_results[kpi_name]['failed'] = failed
                dump_all_results[kpi_name]['avg_from_passed_runs'] = passed_avg
                min_passed = round(min(all_passed_deltas), 2) if all_passed_deltas else None
                max_passed = round(max(all_passed_deltas), 2) if all_passed_deltas else None
                dump_all_results[kpi_name]['min_from_passed_runs'] = min_passed
                dump_all_results[kpi_name]['max_from_passed_runs'] = max_passed
                dump_all_results[kpi_name]['avg'] = total_avg
                dump_all_results[kpi_name]['max'] = round(max(all_deltas), 2)
                dump_all_results[kpi_name]['min'] = round(min(all_deltas), 2)
                dump_all_results[kpi_name]['ratio'] = passed_ratio
            with open(os.path.join(self._robot_log_path, '{}_Kpi_results.json'.format(
                    ssh_bts_du.format(self.bts_type, self.bts_id, self.du_id))), 'w') as f:
                f.write(json.dumps(dump_all_results, indent=4, sort_keys=True, default=str))
            if self.report_to_rep is True:
                passed_iterations, failed_iterations, kpi_name = self._get_iterations_results()
                report_oam_kpi_success_rate(kpi_name=kpi_name, passed_iterations=len(passed_iterations),
                                            executed_iterations=len(failed_iterations) + len(passed_iterations))
        except Exception as e:
            log_info_to_console(traceback.format_exc())
            log_warn_to_console("Failed to calculate final kpi results: {}".format(repr(e)))

    def _get_iterations_results(self):
        dump_all_results = dict(self._all_results)
        del dump_all_results["bts_build"]
        failed_iterations = []
        passed_iterations = []
        kpi_name = sorted(dump_all_results, key=lambda kpi: dump_all_results[kpi]["failed"], reverse=True)[0]
        for it_number in range(1, len(dump_all_results[kpi_name]["results"]) + 1):
            if self._iteration_status[it_number]["status"] == "FAILED" or \
                    any([dump_all_results[kpi]["results"]["iteration_{}".format(it_number)]["status"] == "FAILED"
                         for kpi in list(dump_all_results)]):
                failed_iterations.append(it_number)
            elif self._iteration_status[it_number]["status"] == "PASSED" and \
                    all([dump_all_results[kpi]["results"]["iteration_{}".format(it_number)]["status"] != "FAILED"
                         for kpi in list(dump_all_results)]):
                passed_iterations.append(it_number)
            else:
                self.custom_logger(log_warn_to_console, msg="Iteration {} not specified status".format(it_number),
                                   log_hierarchy=3)
        return passed_iterations, failed_iterations, kpi_name

    @load_moler_configuration_from_tl()
    def get_ims_du_id(self):
        du_devices = [device for device in get_devices_from_regex(pattern=r'{}{}_DU\d+$'.format(self.bts_type,
                                                                                                self.bts_id))]
        ims_du_id = -1 * (len(du_devices) - self.du_id)
        if ims_du_id >= 0:
            raise Exception("Bad ims_du_id")
        return ims_du_id
